# ---- S0626 / G499 SS. John & Paul pp. 475-476 (pdf 276-277); orations came from DO (Sancti/06-26)
for k in ('S0626','G499'):
    SUB('data/orations.js',[k,'or',0],[('Quǽsumus, omnípotens Deus: ut nos','Quǽsumus omnípotens Deus, ut nos'),('festivitátis excípiat, quæ de','festivitátis excípiat: quæ de'),('quos eadem fides','quos éadem fides'),('esse germános. Per Dóminum','esse germános: Per Dóminum')],'M39 p. 475 (pdf 276)','as printed: "Quǽsumus omnípotens Deus, ut"; "excípiat : quæ"; "éadem"; "germános : Per Dóminum"')
    SUB('data/orations.js',[k,'se',0],[('sanctórum Martyrum tuórum','sanctórum Mártyrum tuórum')],'M39 p. 476 (pdf 277)','accent as printed ("Mártyrum")')
    SUB('data/orations.js',[k,'pc',0],[('sanctórum Martyrum tuórum','sanctórum Mártyrum tuórum'),('Pauli sollémnia celebrántes','Pauli solémnia celebrántes'),('sacraménta cœléstia: præsta, quǽsumus; ut, quod temporáliter gérimus, ætérnis gáudiis consequámur. Per Dóminum','sacraménta cæléstia: præsta quǽsumus, ut quod temporáliter gérimus; ætérnis gáudiis consequámur: Per Dóminum')],'M39 p. 476 (pdf 277)','as printed: "Mártyrum"; "solémnia"; "cæléstia : præsta quǽsumus, ut quod temporáliter gérimus; ætérnis gáudiis consequámur : Per Dóminum"')
    SUB('data/readings33.js',[k,0,'la'],[('Viri misericórdiæ sunt','Hi viri misericórdiæ sunt'),('non defuérunt: cum sémine','non defuérunt: Cum sémine'),('nepótes eórum, et in testaméntis','nepótes eórum: Et in testaméntis'),('ætérnum manent: semen eórum','ætérnum manent: Semen eórum')],'M39 p. 475 (pdf 276)','as printed: the Lesson begins "Hi viri misericórdiæ sunt" ("Hi" was missing); capitals and ":" as printed')
    SUB('data/readings33.js',[k,1,'la'],[('Osténdam autem vobis quem timeátis: timéte eum qui, postquam','Osténdam autem vobis, quem timeátis: Timéte eum, qui, postquam'),('míttere in gehénnam: ita dico','míttere in gehénnam. Ita dico'),('coram ángelis Dei','coram Angelis Dei')],'M39 p. 476 (pdf 277)','punctuation and capitals as printed')
